CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150),email VARCHAR(190) UNIQUE,phone VARCHAR(40),password VARCHAR(255),role VARCHAR(20) DEFAULT 'customer',created_at DATETIME NULL);
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150),slug VARCHAR(180),active TINYINT DEFAULT 1);
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NULL,name VARCHAR(200),sku VARCHAR(100),description TEXT,price DECIMAL(12,2),sale_price DECIMAL(12,2) NULL,stock INT DEFAULT 0,active TINYINT DEFAULT 1,created_at DATETIME NULL);
CREATE TABLE IF NOT EXISTS product_images(id INT AUTO_INCREMENT PRIMARY KEY,product_id INT,path VARCHAR(255),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS orders(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) UNIQUE,customer_name VARCHAR(150),phone VARCHAR(40),email VARCHAR(190),address TEXT,note TEXT,payment_method VARCHAR(30),status VARCHAR(30) DEFAULT 'pending',total DECIMAL(12,2),created_at DATETIME NULL);
CREATE TABLE IF NOT EXISTS order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT,product_id INT NULL,product_name VARCHAR(200),qty INT,price DECIMAL(12,2),subtotal DECIMAL(12,2),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
